files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --accent: #6c5ce7;
  --accent-hover: #7d6ff0;
  --accent-pressed: #5a4bd1;
  --muted: #a0a0c0;
  --border: #3a3a55;
  --focus-ring: #fdcb6e;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 1.5rem 1rem;
}

.app {
  width: 100%;
  max-width: 640px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  color: var(--muted);
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  border: 1px solid var(--border);
}

.section-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.mood-fieldset {
  border: none;
  margin-bottom: 1.25rem;
}

.mood-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.mood-option {
  position: relative;
}

.mood-option input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.mood-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  background: transparent;
  color: var(--text);
  font-size: 1rem;
  min-width: 64px;
}

.mood-label:hover {
  background: rgba(108, 92, 231, 0.15);
}

.mood-label:focus-within {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.mood-option input[type="radio"]:checked + .mood-label {
  border-color: var(--accent);
  background: rgba(108, 92, 231, 0.25);
}

.mood-option input[type="radio"]:active + .mood-label {
  background: rgba(108, 92, 231, 0.35);
}

.mood-face {
  font-size: 2rem;
  line-height: 1;
}

.mood-name {
  font-size: 0.875rem;
  color: var(--muted);
}

.note-area {
  margin-bottom: 1.25rem;
}

.label {
  display: block;
  font-size: 1rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
}

textarea {
  width: 100%;
  padding: 0.75rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  resize: vertical;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--focus-ring);
}

.help-text {
  font-size: 0.875rem;
  color: var(--muted);
  margin-top: 0.25rem;
}

.btn-primary {
  display: block;
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn-primary:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.summary-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}

.summary-list li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.05);
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.9375rem;
}

.summary-face {
  font-size: 1.25rem;
}

.entries-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.entry {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 8px;
  border-left: 4px solid var(--accent);
}

.entry-face {
  font-size: 1.5rem;
  line-height: 1;
}

.entry-content {
  flex: 1;
  min-width: 0;
}

.entry-meta {
  font-size: 0.8125rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

.entry-note {
  word-break: break-word;
}

.empty-msg {
  color: var(--muted);
  font-style: italic;
  text-align: center;
  padding: 1rem 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

@media (max-width: 400px) {
  body {
    padding: 1rem 0.5rem;
  }
  .card {
    padding: 1rem;
  }
  .title {
    font-size: 1.5rem;
  }
  .mood-grid {
    gap: 0.5rem;
  }
  .mood-label {
    min-width: 52px;
    padding: 0.375rem;
  }
  .mood-face {
    font-size: 1.75rem;
  }
}

(function () {
  'use strict';

  const MOODS = [
    { id: 'happy',   face: '😊', label: 'Happy' },
    { id: 'sad',     face: '😢', label: 'Sad' },
    { id: 'angry',   face: '😠', label: 'Angry' },
    { id: 'tired',   face: '😴', label: 'Tired' },
    { id: 'excited', face: '🤩', label: 'Excited' }
  ];

  const STORAGE_KEY = 'pixelMoodJournalEntries';

  const moodGrid = document.getElementById('mood-grid');
  const noteInput = document.getElementById('note-input');
  const addBtn = document.getElementById('add-entry');
  const moodSummary = document.getElementById('mood-summary');
  const entriesList = document.getElementById('entries-list');

  let entries = loadEntries();

  function loadEntries() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function saveEntries() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));
    } catch (e) {
      // localStorage may be unavailable; silently ignore
    }
  }

  function getTodayDate() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return yyyy + '-' + mm + '-' + dd;
  }

  function renderMoodOptions() {
    moodGrid.innerHTML = '';
    MOODS.forEach(function (mood, index) {
      const wrapper = document.createElement('div');
      wrapper.className = 'mood-option';

      const input = document.createElement('input');
      input.type = 'radio';
      input.name = 'mood';
      input.id = 'mood-' + mood.id;
      input.value = mood.id;
      if (index === 0) input.checked = true;

      const label = document.createElement('label');
      label.className = 'mood-label';
      label.htmlFor = 'mood-' + mood.id;

      const faceSpan = document.createElement('span');
      faceSpan.className = 'mood-face';
      faceSpan.textContent = mood.face;
      faceSpan.setAttribute('aria-hidden', 'true');

      const nameSpan = document.createElement('span');
      nameSpan.className = 'mood-name';
      nameSpan.textContent = mood.label;

      label.appendChild(faceSpan);
      label.appendChild(nameSpan);

      wrapper.appendChild(input);
      wrapper.appendChild(label);
      moodGrid.appendChild(wrapper);
    });
  }

  function getSelectedMood() {
    const checked = moodGrid.querySelector('input[name="mood"]:checked');
    return checked ? checked.value : MOODS[0].id;
  }

  function getMoodById(id) {
    return MOODS.find(function (m) { return m.id === id; }) || MOODS[0];
  }

  function addEntry() {
    const moodId = getSelectedMood();
    const note = noteInput.value.trim().slice(0, 140);
    const entry = {
      id: Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      mood: moodId,
      note: note,
      date: getTodayDate(),
      timestamp: Date.now()
    };
    entries.push(entry);
    saveEntries();
    noteInput.value = '';
    renderAll();
  }

  function renderSummary() {
    const counts = {};
    MOODS.forEach(function (m) { counts[m.id] = 0; });
    entries.forEach(function (e) {
      if (counts[e.mood] !== undefined) counts[e.mood]++;
    });

    moodSummary.innerHTML = '';
    MOODS.forEach(function (m) {
      const li = document.createElement('li');
      li.setAttribute('aria-label', m.label + ': ' + counts[m.id] + ' entries');

      const face = document.createElement('span');
      face.className = 'summary-face';
      face.textContent = m.face;
      face.setAttribute('aria-hidden', 'true');

      const text = document.createElement('span');
      text.textContent = m.label + ': ' + counts[m.id];

      li.appendChild(face);
      li.appendChild(text);
      moodSummary.appendChild(li);
    });
  }

  function renderEntries() {
    const sorted = entries.slice().sort(function (a, b) {
      return b.timestamp - a.timestamp;
    });

    entriesList.innerHTML = '';
    if (sorted.length === 0) {
      const li = document.createElement('li');
      li.className = 'empty-msg';
      li.textContent = 'No entries yet. Add your first mood above!';
      entriesList.appendChild(li);
      return;
    }

    sorted.forEach(function (entry) {
      const mood = getMoodById(entry.mood);
      const li = document.createElement('li');
      li.className = 'entry';

      const faceSpan = document.createElement('span');
      faceSpan.className = 'entry-face';
      faceSpan.textContent = mood.face;
      faceSpan.setAttribute('aria-hidden', 'true');

      const content = document.createElement('div');
      content.className = 'entry-content';

      const meta = document.createElement('div');
      meta.className = 'entry-meta';
      meta.textContent = entry.date + ' · ' + mood.label;

      content.appendChild(meta);

      if (entry.note) {
        const note = document.createElement('div');
        note.className = 'entry-note';
        note.textContent = entry.note;
        content.appendChild(note);
      }

      li.appendChild(faceSpan);
      li.appendChild(content);
      entriesList.appendChild(li);
    });
  }

  function renderAll() {
    renderSummary();
    renderEntries();
  }

  // Limit note length
  noteInput.addEventListener('input', function () {
    if (noteInput.value.length > 140) {
      noteInput.value = noteInput.value.slice(0, 140);
    }
  });

  addBtn.addEventListener('click', addEntry);

  // Initialize
  renderMoodOptions();
  renderAll();
})();
